// TypeScript: minimal session proxy usage
const session = sdk.createSessionProxy({validator: mySchemaValidator});
for await (const ev of session.invokeTool('code-runner', {stdin: 'print(1)'}) ) {
  if (ev.type === 'progress') console.log(ev.payload.percent);
  if (ev.type === 'output') {
    const result = await session.validateOutput(ev.payload);
    console.log('structured result', result);
  }
}
# Python: minimal session proxy usage
from sdk import create_session_proxy
session = create_session_proxy(validator=my_pydantic_validator)
async for ev in session.invoke_tool('search', {'q': 'redwood'}):
    if ev['type'] == 'progress':
        print('progress', ev['payload']['percent'])
    if ev['type'] == 'output':
        validated = session.validate_output(ev['payload'])
        print('structured', validated)
// Go: minimal session proxy usage
sp := sessionproxy.New(sessionproxy.Options{Validator: myValidator})
ch := sp.InvokeTool(ctx, "summarize", map[string]any{"text": longText})
for ev := range ch {
  switch ev.Type {
  case sessionproxy.EventProgress:
    fmt.Println("progress", ev.Payload["percent"])
  case sessionproxy.EventOutput:
    out, _ := sp.ValidateOutput(ev.Payload)
    fmt.Println("structured", out)
  }
}
